DO $$ DECLARE n text; r record; BEGIN FOR r IN SELECT unnest(ARRAY['office_senior_members','office_requests','office_login_logs','office_click_logs','office_archive','office_case_categories','client_files','task_feedback','task_followups','financial_dues']) AS name LOOP n:=r.name; IF EXISTS (SELECT 1 FROM pg_type WHERE typname=n AND typnamespace='public'::regnamespace) AND NOT EXISTS (SELECT 1 FROM pg_class WHERE relname=n AND relnamespace='public'::regnamespace) THEN EXECUTE format('DROP TYPE IF EXISTS public.%I',n); END IF; END LOOP; END $$;
CREATE TABLE IF NOT EXISTS "office_senior_members" ("id" text PRIMARY KEY,"user_id" text,"lawyer_id" text,"title" text NOT NULL DEFAULT 'إدارة عليا',"created_at" timestamptz NOT NULL DEFAULT now(),CONSTRAINT "office_senior_members_identity" CHECK (("user_id" IS NOT NULL) OR ("lawyer_id" IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS "office_senior_members_user_uq" ON "office_senior_members"("user_id") WHERE "user_id" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "office_senior_members_lawyer_uq" ON "office_senior_members"("lawyer_id") WHERE "lawyer_id" IS NOT NULL;
CREATE TABLE IF NOT EXISTS "office_requests" ("id" text PRIMARY KEY,"type" text NOT NULL,"title" text NOT NULL,"reason" text,"payload_json" jsonb NOT NULL DEFAULT '{}'::jsonb,"requested_by_user_id" text,"requested_by_lawyer_id" text,"target_entity_type" text,"target_entity_id" text,"status" text NOT NULL DEFAULT 'PENDING',"decided_by_user_id" text,"decided_at" timestamptz,"decision_note" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "office_requests_status_created_idx" ON "office_requests"("status","created_at" DESC);CREATE INDEX IF NOT EXISTS "office_requests_type_idx" ON "office_requests"("type");
CREATE TABLE IF NOT EXISTS "office_login_logs" ("id" text PRIMARY KEY,"user_id" text,"lawyer_id" text,"login_at" timestamptz NOT NULL DEFAULT now(),"logout_at" timestamptz,"last_seen_at" timestamptz,"duration_seconds" integer,"ip" text,"user_agent" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "office_login_logs_actor_idx" ON "office_login_logs"("lawyer_id","login_at" DESC);CREATE INDEX IF NOT EXISTS "office_login_logs_user_idx" ON "office_login_logs"("user_id","login_at" DESC);
CREATE TABLE IF NOT EXISTS "office_click_logs" ("id" text PRIMARY KEY,"user_id" text,"lawyer_id" text,"label" text,"target" text,"path" text,"created_at" timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS "office_click_logs_created_idx" ON "office_click_logs"("created_at" DESC);
CREATE TABLE IF NOT EXISTS "office_archive" ("id" text PRIMARY KEY,"entity_type" text NOT NULL,"entity_id" text NOT NULL,"label" text,"snapshot_json" jsonb NOT NULL,"deleted_by_user_id" text,"deleted_by_lawyer_id" text,"deleted_at" timestamptz NOT NULL DEFAULT now(),"restored_at" timestamptz,"restored_by_user_id" text);CREATE INDEX IF NOT EXISTS "office_archive_deleted_idx" ON "office_archive"("deleted_at" DESC);CREATE INDEX IF NOT EXISTS "office_archive_type_idx" ON "office_archive"("entity_type");
CREATE TABLE IF NOT EXISTS "office_case_categories" ("id" text PRIMARY KEY,"name_ar" text NOT NULL,"name_en" text NOT NULL DEFAULT '',"sort_order" integer NOT NULL DEFAULT 100,"active" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
ALTER TABLE "case_records" ADD COLUMN IF NOT EXISTS "category_id" text;ALTER TABLE "case_records" ADD COLUMN IF NOT EXISTS "archived_at" timestamptz;CREATE INDEX IF NOT EXISTS "case_records_category_idx" ON "case_records"("category_id");
CREATE TABLE IF NOT EXISTS "client_files" ("id" text PRIMARY KEY,"client_id" text NOT NULL,"name" text NOT NULL,"kind" text NOT NULL,"mime_type" text,"size_bytes" integer,"url" text,"text_content" text,"created_by_user_id" text,"created_by_lawyer_id" text,"created_at" timestamptz NOT NULL DEFAULT now(),"deleted_at" timestamptz);CREATE INDEX IF NOT EXISTS "client_files_client_idx" ON "client_files"("client_id","created_at" DESC);
ALTER TABLE "clients" ADD COLUMN IF NOT EXISTS "status" text NOT NULL DEFAULT 'MAIN';ALTER TABLE "clients" ADD COLUMN IF NOT EXISTS "archived_at" timestamptz;ALTER TABLE "clients" ADD COLUMN IF NOT EXISTS "rejection_reason" text;
CREATE TABLE IF NOT EXISTS "task_feedback" ("id" text PRIMARY KEY,"task_id" text NOT NULL UNIQUE,"feedback" text,"result" text,"created_by_user_id" text,"created_by_lawyer_id" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "task_followups" ("id" text PRIMARY KEY,"parent_task_id" text NOT NULL,"child_task_id" text NOT NULL,"relation_type" text NOT NULL DEFAULT 'FOLLOW_UP',"created_by_user_id" text,"created_by_lawyer_id" text,"created_at" timestamptz NOT NULL DEFAULT now(),UNIQUE("parent_task_id","child_task_id"));CREATE INDEX IF NOT EXISTS "task_followups_parent_idx" ON "task_followups"("parent_task_id","created_at" DESC);
CREATE TABLE IF NOT EXISTS "financial_dues" ("id" text PRIMARY KEY,"lawyer_id" text,"description" text NOT NULL,"amount" numeric(14,2) NOT NULL DEFAULT 0,"status" text NOT NULL DEFAULT 'PENDING',"created_at" timestamptz NOT NULL DEFAULT now(),"paid_at" timestamptz);
INSERT INTO "office_case_categories" ("id","name_ar","name_en","sort_order") VALUES ('casecat_contracts','العقود','Contracts',10),('casecat_incorporation','التأسيس','Incorporation',20),('casecat_companies','الشركات','Companies',30),('casecat_active','القضايا المتداولة','Active Litigation',40),('casecat_review','القضايا تحت المراجعة','Under Review',50),('casecat_minutes','المحاضر','Minutes',60),('casecat_litigation','التقاضي','Litigation',70),('casecat_arbitration','التحكيم','Arbitration',80) ON CONFLICT ("id") DO NOTHING;
